"use strict";

// Turn an arbitrary title into a URL slug. Keep a trailing four-digit year as
// a distinct token, separated from the title with an underscore.
function slugify(title) {
  return title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .replace(/-(\d{4})$/, "_$1");
}

module.exports = { slugify };

